#define NP_CL_PRESET_COUNT (sizeof(np_cl_presets)/sizeof(np_cl_presets[0]))
static int np_cl_coefficients_get(NpClRate rate, uint32_t filter, NpClCoefficients *out) {
  uint32_t i; if(!out) return 0;
  out->rate.num=out->rate.den=out->main_count=out->envelope_count=0U; out->main=out->envelope=0;
  if(!rate.num || !rate.den) return 0;
  for(i=0;i<NP_CL_PRESET_COUNT;i++) { const NpClPreset *p=&np_cl_presets[i];
    if(filter==p->filter && (uint64_t)rate.num*p->rate.den==(uint64_t)p->rate.num*rate.den) {
      out->rate=rate; out->main=p->band; out->envelope=p->envelope; out->main_count=out->envelope_count=3U; return 1;
    }
  } return 0;
}
